<script setup>
import {useDramaI18n} from './useDramaI18n.js';
const {language,tr}=useDramaI18n();
import BaseModal from '../components/BaseModal.vue';
import {ref,computed,watch,nextTick} from 'vue';import {dramaImages} from './images.js';
const props=defineProps({drama:{type:Object,required:true}});const images=computed(()=>dramaImages(props.drama));const index=ref(0),failed=ref(false),zoom=ref(false),zoomFailed=ref(false);let touchX=0,swiped=false;function openImage(){if(swiped){swiped=false;return;}zoom.value=true;}
watch(zoom,async value=>{if(value){zoomFailed.value=false;await nextTick();requestAnimationFrame(()=>document.querySelector('.drama-image-lightbox .zoom-gallery')?.focus());}});
function swipe(event){const distance=event.changedTouches[0].clientX-touchX;if(Math.abs(distance)>45&&images.value.length>1){swiped=true;move(distance<0?1:-1);}}
watch(()=>props.drama.id,()=>{index.value=0;failed.value=false;});watch(()=>images.value.join('|'),()=>{index.value=0;failed.value=false;});watch(index,()=>{failed.value=false;zoomFailed.value=false;});
function move(n){index.value=(index.value+n+images.value.length)%images.value.length;}
</script>
<template><section v-if="images.length" class="drama-gallery" :aria-label="tr('剧集图片')"><button type="button" class="gallery-open" @click="openImage" :aria-label="tr('放大图片')" @touchstart.passive="touchX=$event.changedTouches[0].clientX;swiped=false" @touchend.passive="swipe"><Transition name="picture" mode="out-in"><img v-if="!failed" :key="images[index]" class="drama-main-image" :src="images[index]" :alt="index===0?'剧集主海报':'剧集附图 '+(index+1)" @error="failed=true"><span v-else class="image-failed">{{tr('图片暂时无法加载，点击放大重试')}}</span></Transition></button><div v-if="images.length>1" class="gallery-controls"><button v-if="images.length>1" type="button" @click="move(-1)" :aria-label="tr('上一张图片')">‹</button><span aria-live="polite">{{tr(index===0?'主海报':'图片')+(index===0?'':' '+(index+1))}} · {{index+1}} / {{images.length}}</span><button v-if="images.length>1" type="button" @click="move(1)" :aria-label="tr('下一张图片')">›</button></div></section><BaseModal v-if="zoom" :title="tr('图片')" panel-class="drama-image-lightbox" @close="zoom=false"><div class="zoom-gallery" tabindex="0" :aria-label="tr('剧集图片')" @keydown.left.prevent="move(-1)" @keydown.right.prevent="move(1)" @touchstart.passive="touchX=$event.changedTouches[0].clientX;swiped=false" @touchend.passive="swipe"><Transition name="picture" mode="out-in"><img v-if="!zoomFailed" :key="images[index]" :src="images[index]" :alt="tr('剧集图片')" @error="zoomFailed=true"><div v-else class="image-failed" role="alert"><p>{{tr('图片暂时无法加载，点击放大重试')}}</p><button @click="zoomFailed=false">{{tr('重试图片')}}</button></div></Transition><div v-if="images.length>1" class="gallery-controls"><button @click="move(-1)" :aria-label="tr('上一张大图')">‹</button><span>{{index+1}} / {{images.length}}</span><button @click="move(1)" :aria-label="tr('下一张大图')">›</button></div></div></BaseModal></template>
<style scoped>.drama-gallery{margin:12px 0 20px}.drama-main-image{display:block;width:100%;height:auto;max-height:440px;object-fit:contain;border-radius:8px;background:#F1F4F7}.gallery-controls{display:flex;align-items:center;justify-content:center;gap:16px;margin:10px 0;font-size:12px;color:#7d857d}.gallery-controls button{border:0;background:none;font-size:24px;cursor:pointer;color:#303b35}.gallery-controls a{font-size:12px;color:#5E83AE}.gallery-thumbs{display:flex;gap:10px;overflow-x:auto;padding:4px 0}.gallery-thumbs button{flex:0 0 65px;height:80px;border:2px solid transparent;padding:2px;border-radius:6px;background:#F1F4F7;cursor:pointer}.gallery-thumbs button.active{border-color:#5E83AE}.gallery-thumbs img{width:100%;height:100%;object-fit:contain}.image-failed{display:grid;place-items:center;min-height:180px;color:#7d857d;font-size:13px}@media(max-width:500px){.drama-main-image{max-height:55dvh}.gallery-controls{gap:10px}}
.gallery-open{display:block;padding:0;width:100%;border:0;background:none;cursor:zoom-in;color:inherit}.picture-enter-active,.picture-leave-active{transition:opacity .16s ease,transform .16s ease}.picture-enter-from,.picture-leave-to{opacity:0;transform:translateX(6px)}.zoom-gallery img{display:block;max-width:100%;height:auto;max-height:75dvh;object-fit:contain;margin:auto}.zoom-gallery{touch-action:pan-y}@media(prefers-reduced-motion:reduce){.picture-enter-active,.picture-leave-active{transition:none}}</style><style>.modal.drama-image-lightbox{width:min(1100px,calc(100vw - 24px));max-width:min(1100px,calc(100vw - 24px));background:#fff}.drama-image-lightbox .modal-content{padding:0 12px 12px}</style>
